Channels.Mechanical:
var v[6];

for (var n := 0; n < 6; n += 1) {
    if (n == 0)
        v[n] := demodulateAtFrequency(n * HeadFrequency);
    else
        v[n] := demodulateAtFrequency(n * HeadFrequency) * scaling;
}

return [v];

Channels.Optical:
 var v[6];

 for (var n := 0; n < 6; n += 1) {
    v[n] := demodulateAtFrequency(n * HeadFrequency + demodOrder * chopperFrequency) * scaling
}

return [v];
